// Des: Marketplace: list, renew and mark sold, with a ledger
// Flo: list = fill form + publish + ledger row (exact title, group, time) > renew/sold = find the listing by title in the selling page > ledger update
// I/O: Args title, price, desc, group, photo (caller) > Out; ledger rows in state db; same listing is never published twice
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const flow = @import("ru-flow-runz.zig"); const post = @import("ru-post-main.zig"); const fld = @import("ut-text-fold.zig");
const CF = .{ .titl = "Array.from(document.querySelectorAll('[role=article] h2')).map(function(e){return e.innerText.trim()})", .lidz = "document.body.getAttribute('data-listing-id')||''", .dayz = 86400000 };
pub fn listRun(ctx: *task.Ctx, args: task.Args) !task.Out { if (args.title.len == 0 or args.price.len == 0) return error.BadUsage; const hsh = try task.hashHex(ctx, try std.fmt.allocPrint(ctx.aren, "{s}|{s}|{s}", .{ args.title, args.price, args.desc })); const key = try std.fmt.allocPrint(ctx.aren, "list|{s}", .{hsh}); const what = try std.fmt.allocPrint(ctx.aren, "list \"{s}\" for {s} (group: {s})", .{ post.cutUtf8(args.title, 40), args.price, if (args.group.len > 0) args.group else "-" }); var stps: std.ArrayList(flow.Step) = .empty; try stps.append(ctx.aren, task.goStep(ctx.conf.path_mark_crea)); try stps.append(ctx.aren, .{ .op = .typez, .labs = ctx.conf.labl_mark_titl, .text = args.title }); try stps.append(ctx.aren, .{ .op = .typez, .labs = ctx.conf.labl_mark_pric, .text = args.price }); if (args.desc.len > 0) try stps.append(ctx.aren, .{ .op = .typez, .labs = ctx.conf.labl_mark_desc, .text = args.desc }); if (args.photo.len > 0) try stps.append(ctx.aren, .{ .op = .upload, .text = args.photo }); try stps.append(ctx.aren, .{ .op = .click, .labs = ctx.conf.labl_mark_subm, .commit = true }); try stps.append(ctx.aren, .{ .op = .expect, .labs = ctx.conf.labl_mark_done }); const out = try task.execWrite(ctx, .mark, key, what, false, stps.items); if (out == .done) { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const lid = ctx.page.evalStr(ctx.aren, CF.lidz) catch ""; _ = try ctx.store.ledgAdd(if (lid.len > 0) lid else hsh, args.title, args.group, task.nowMs(ctx)); } return out; }
const Hit = struct { idx: usize, titl: []const u8 };
fn findIdx(ctx: *task.Ctx, title: []const u8) !Hit { try task.visit(ctx, ctx.conf.path_mark_sell); const tls = try task.jsList(ctx, CF.titl); const want = try fld.foldAlloc(ctx.aren, std.mem.trim(u8, title, " ")); for (tls, 0..) |tit, idx| { const got = try fld.foldAlloc(ctx.aren, tit); if (std.mem.eql(u8, got, want)) return .{ .idx = idx, .titl = tit }; } return error.NoElement; }
fn rowAct(ctx: *task.Ctx, title: []const u8, labs: []const []const u8, verb: []const u8, keyx: []const u8, exact: *[]const u8) !task.Out { if (title.len == 0) return error.BadUsage; const hit = try findIdx(ctx, title); const idx = hit.idx; exact.* = hit.titl; const key = try std.fmt.allocPrint(ctx.aren, "{s}|{s}|{s}", .{ verb, hit.titl, keyx }); const what = try std.fmt.allocPrint(ctx.aren, "{s} listing \"{s}\"", .{ verb, post.cutUtf8(title, 40) }); const stps = try ctx.aren.dupe(flow.Step, &.{ task.goStep(ctx.conf.path_mark_sell), .{ .op = .click, .labs = labs, .nth = idx, .commit = true } }); return task.execWrite(ctx, .mark, key, what, false, stps); }
pub fn renewRun(ctx: *task.Ctx, args: task.Args) !task.Out { const day = try std.fmt.allocPrint(ctx.aren, "{d}", .{@divFloor(task.nowMs(ctx), CF.dayz)}); var exa: []const u8 = ""; const out = try rowAct(ctx, args.title, ctx.conf.labl_mark_renw, "renew", day, &exa); if (out == .done) _ = try ctx.store.ledgSet(exa, "live", task.nowMs(ctx)); return out; }
pub fn soldRun(ctx: *task.Ctx, args: task.Args) !task.Out { var exa: []const u8 = ""; const out = try rowAct(ctx, args.title, ctx.conf.labl_mark_sold, "sold", "", &exa); if (out == .done) _ = try ctx.store.ledgSet(exa, "sold", task.nowMs(ctx)); return out; }
